(46361, 'Exodus 15:10', 'Exodus', 15, 10, 'خو تا وکړ یو پوکی او کړل لاندې بحیرې هغوی په زورورو اوبو کې هغوی ډوب شول لکه د سرپو په شان', 'خو تا وکر یو پوکی او کرل لاندې بحیرې هغوی په زورورو اوبو کې هغوی دوب شول لکه د سرپو په شان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_10.mp3', 'https://drive.google.com/uc?id=1StTe8XY9dkcrwNdYMqpVuLn5UP-ycZSK&export=download', 1761237844, 1761237844),
(46362, 'Exodus 15:11', 'Exodus', 15, 11, 'د خدایانو منځ کې څوک ستا په شان دی ای څښتنه؟ څوک دی ستا په شان؟ ته سپېڅلی یې او لوی یې ستا جلال دی هیبتناکه ته کوې عجیب عجیب کارونه', 'د خدایانو منج کې چوک ستا په شان دی ای چشتنه؟ چوک دی ستا په شان؟ ته سپېچلی یې او لوی یې ستا جلال دی هیبتناکه ته کوې عجیب عجیب کارونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_11.mp3', 'https://drive.google.com/uc?id=1LSXHEhFYDN24-QbOWOidYch3i7auvbjq&export=download', 1761237844, 1761237844),
(46363, 'Exodus 15:12', 'Exodus', 15, 12, 'تا کړ اوږد خپل ښي لاس او ژوندي تېر کړل ځمکې زمونږ دښمنان', 'تا کر اوزد خپل شی لاس او ژوندی تېر کرل جمکې زمونز دشمنان', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_12.mp3', 'https://drive.google.com/uc?id=1dbWtjGLbZpT9hcZxdp9B03JKX4xOskRQ&export=download', 1761237844, 1761237844),
(46364, 'Exodus 15:13', 'Exodus', 15, 13, 'تل ولاړ په خپل وعده یې کړې به خپل قوم ته لارښوونه کوم چې ژغورلی دی تا په خپل قوت سره به بوځې ته هغوی سپېڅلې ځمکې ته خپل', 'تل ولار په خپل وعده یې کرې به خپل قوم ته لارشوونه کوم چې ژغورلی دی تا په خپل قوت سره به بوجې ته هغوی سپېچلې جمکې ته خپل', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_13.mp3', 'https://drive.google.com/uc?id=1kAWmoM_lTRRWSKIX1kstAnSNzZ9Dl9pN&export=download', 1761237844, 1761237844),
(46365, 'Exodus 15:14', 'Exodus', 15, 14, 'شي قومونه به خبر او په لړزان به شي د فلسطین په قوم به راشي سخته وېره', 'شی قومونه به خبر او په لرزان به شی د فلسطین په قوم به راشی سخته وېره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_14.mp3', 'https://drive.google.com/uc?id=1Ra7EnbJ2OCNvHho2kv-EIeufu-4dhgZ2&export=download', 1761237844, 1761237844),
(46366, 'Exodus 15:15', 'Exodus', 15, 15, 'وبه وېریږي ډېر د ادوم مشران شي په لړزه به د موآب مشران د کنعان خلک به له لاسه ورکړي خپل همت', 'وبه وېریزی دېر د ادوم مشران شی په لرزه به د مواب مشران د کنعان خلک به له لاسه ورکری خپل همت', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_15.mp3', 'https://drive.google.com/uc?id=1hGEbz8DucVeZhJDgEhqSysIZJ-FP-Lvf&export=download', 1761237844, 1761237844),
(46367, 'Exodus 15:16', 'Exodus', 15, 16, 'په هغوی باندې به پرېوځي سخته وېره او لړزه ستا د مټ په زور باندې به وي غلي هغوی لکه د تیږې په شان تر هغه وخته پورې ترڅو تېر شي ای څښتنه ستا قوم ترڅو تېر شي ستا قوم چې ازاد کړی دی تا د غلامۍ نه', 'په هغوی باندې به پرېوجی سخته وېره او لرزه ستا د مت په زور باندې به وی غلی هغوی لکه د تیزې په شان تر هغه وخته پورې ترچو تېر شی ای چشتنه ستا قوم ترچو تېر شی ستا قوم چې ازاد کری دی تا د غلامی نه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_16.mp3', 'https://drive.google.com/uc?id=1XDcEeMFQvKw2IuJc-RwiYU-_8gIhQSq5&export=download', 1761237844, 1761237844),
(46368, 'Exodus 15:17', 'Exodus', 15, 17, 'ته به راولې هغوی دننه او ځای په ځای به یې کړې ته په خپل غره باندې هغه ځای څښتنه چې غوره کړی دی تا د خپل کور دپاره سپېڅلی ځای چې ودان کړی تا په خپله', 'ته به راولې هغوی دننه او جای په جای به یې کرې ته په خپل غره باندې هغه جای چشتنه چې غوره کری دی تا د خپل کور دپاره سپېچلی جای چې ودان کری تا په خپله', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_17.mp3', 'https://drive.google.com/uc?id=1sXkl-JhZs94gTEQ9dOGBwIThHCzSuOaY&export=download', 1761237844, 1761237844),
(46369, 'Exodus 15:18', 'Exodus', 15, 18, 'پاچاهي به کاندي تل ترتله به څښتن', 'پاچاهی به کاندی تل ترتله به چشتن', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_18.mp3', 'https://drive.google.com/uc?id=12s9YMftgSkLIb0cv8VfhqZD2ljfxOfyX&export=download', 1761237844, 1761237844),
(46370, 'Exodus 15:19', 'Exodus', 15, 19, 'کله چې د فرعون اسونه، جنګي ګاډۍ او سپاره بحیرې ته ورداخل شول، څښتن په هغوی باندې اوبه بېرته راوستلې. خو اسراییلیان په بحیره کې په وچه ځمکه باندې تېر شول.', 'کله چې د فرعون اسونه، جنګی ګادی او سپاره بحیرې ته ورداخل شول، چشتن په هغوی باندې اوبه بېرته راوستلې. خو اسراییلیان په بحیره کې په وچه جمکه باندې تېر شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_19.mp3', 'https://drive.google.com/uc?id=1KhBTG_4ny8GCep8zKvlk-mxnTCGnlYdK&export=download', 1761237844, 1761237844),
(46371, 'Exodus 15:20', 'Exodus', 15, 20, 'بیا مریم د هارون خور چې پیغمبره وه په خپل لاس کې یوه چمبه واخیستله او ټولې ښځې د چمبو سره ورپسې شوې او نڅا یې کوله.', 'بیا مریم د هارون خور چې پیغمبره وه په خپل لاس کې یوه چمبه واخیستله او تولې شجې د چمبو سره ورپسې شوې او نچا یې کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_20.mp3', 'https://drive.google.com/uc?id=1o_AL4dOzTEnFGi_EMgc95znw-9Bl20zk&export=download', 1761237844, 1761237844),
(46372, 'Exodus 15:21', 'Exodus', 15, 21, 'مریم د هغوی دپاره دا سندره وویله: سندره ووایئ څښتن ته ځکه هغه بریالی شوی دی په سرلوړۍ سره هغه اسونه او سپاره دي غورځولي بحیرې ته', 'مریم د هغوی دپاره دا سندره وویله: سندره ووایی چشتن ته جکه هغه بریالی شوی دی په سرلوری سره هغه اسونه او سپاره دی غورجولی بحیرې ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_21.mp3', 'https://drive.google.com/uc?id=1c-rgDnL6xcHVtN7fUElVOOx0sayfkzv9&export=download', 1761237844, 1761237844),
(46373, 'Exodus 15:22', 'Exodus', 15, 22, 'بیا موسی اسراییلیان د سرې بحیرې څخه د شور دښتې ته بوتلل. درې ورځې هغوی په دښته کې روان وو، خو اوبه یې ونه موندلې.', 'بیا موسی اسراییلیان د سرې بحیرې چخه د شور دشتې ته بوتلل. درې ورجې هغوی په دشته کې روان وو، خو اوبه یې ونه موندلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_22.mp3', 'https://drive.google.com/uc?id=11kXfeOj5OjY8JljQTbVSj_T_RPk6yjYz&export=download', 1761237844, 1761237844),
(46374, 'Exodus 15:23', 'Exodus', 15, 23, 'بیا هغوی یو ځای ته چې ماره نومېده، راغلل. خو د هغه ځای اوبه ډېرې ترخې وې او هغوی نه شو کولای چې هغه وڅښي. له دې امله په هغه باندې د ماره نوم کېښودل شو.', 'بیا هغوی یو جای ته چې ماره نومېده، راغلل. خو د هغه جای اوبه دېرې ترخې وې او هغوی نه شو کولای چې هغه وچشی. له دې امله په هغه باندې د ماره نوم کېشودل شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_23.mp3', 'https://drive.google.com/uc?id=1UcC0ORCs1aF3MMFWDqyP-rx7kFQLiFzK&export=download', 1761237844, 1761237844),
(46375, 'Exodus 15:24', 'Exodus', 15, 24, 'نو خلک د موسی په وړاندې راپورته شول او ویې ویل: «مونږ به څه څښو؟»', 'نو خلک د موسی په وراندې راپورته شول او ویې ویل: «مونز به چه چشو؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_24.mp3', 'https://drive.google.com/uc?id=1Tqh_rxeLyXuBWyZGoX4G4Xhjc9ykesFT&export=download', 1761237844, 1761237844),
(46376, 'Exodus 15:25', 'Exodus', 15, 25, 'بیا موسی څښتن ته زارۍ وکړې او څښتن ورته د لرګي یوه ټوټه وروښودله. موسی هغه په اوبو کې وغورځوله او اوبه خوږې شوې. څښتن هلته هغوی ته قوانین ورکړل چې د هغو له مخې ژوند وکړي او هغوی وازمایي چې د هغه قوانینو ته غاړه ږدي او که نه.', 'بیا موسی چشتن ته زاری وکرې او چشتن ورته د لرګی یوه توته وروشودله. موسی هغه په اوبو کې وغورجوله او اوبه خوزې شوې. چشتن هلته هغوی ته قوانین ورکرل چې د هغو له مخې ژوند وکری او هغوی وازمایی چې د هغه قوانینو ته غاره زدی او که نه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_25.mp3', 'https://drive.google.com/uc?id=1X3YbAYp9sXGQ_GeNwHC76t2UEG3ihvwg&export=download', 1761237844, 1761237844),
(46377, 'Exodus 15:26', 'Exodus', 15, 26, 'هغه وویل: «که چېرې تاسو خپل څښتن خدای ته په غور سره غوږ ونیسئ او هغه څه وکړئ چې د هغه په نظر کې ښه دي او که چېرې تاسو د هغه په امرونو باندې عمل وکړئ او د هغه د فرمانونو څخه پیروي وکړئ، نو زه به په تاسو باندې هغه ناروغۍ نازلې نه کړم کومې چې ما په مصریانو باندې نازلې کړې وې. ځکه چې زه څښتن یم او زه تاسو ته شفا درکوونکی یم.»', 'هغه وویل: «که چېرې تاسو خپل چشتن خدای ته په غور سره غوز ونیسی او هغه چه وکری چې د هغه په نظر کې شه دی او که چېرې تاسو د هغه په امرونو باندې عمل وکری او د هغه د فرمانونو چخه پیروی وکری، نو زه به په تاسو باندې هغه ناروغی نازلې نه کرم کومې چې ما په مصریانو باندې نازلې کرې وې. جکه چې زه چشتن یم او زه تاسو ته شفا درکوونکی یم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_26.mp3', 'https://drive.google.com/uc?id=1n6gc1CWJFUAonP3GmI6is1MvCwsb4P9_&export=download', 1761237844, 1761237844),
(46378, 'Exodus 15:27', 'Exodus', 15, 27, 'بیا هغوی ایلیم ته راغلل. هلته دولس چینې او د خرما اویا ونې وې. نو هغوی هلته د چینو په غاړه خېمې ودرولې.', 'بیا هغوی ایلیم ته راغلل. هلته دولس چینې او د خرما اویا ونې وې. نو هغوی هلته د چینو په غاره خېمې ودرولې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_15_27.mp3', 'https://drive.google.com/uc?id=1MG6hGdfUA8fEOT-BU7hHz9e4zhgB5Exk&export=download', 1761237844, 1761237844),
(46379, 'Judges 3:1', 'Judges', 3, 1, 'نو څښتن په کنعان کې ځینې قومونه پرېښودل چې د هغوی په وسیله هغه اسراییلیان وازمایي چې د کنعان په جګړو کې یې برخه نه وه اخیستې.', 'نو چشتن په کنعان کې جینې قومونه پرېشودل چې د هغوی په وسیله هغه اسراییلیان وازمایی چې د کنعان په جګرو کې یې برخه نه وه اخیستې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges003_verse_001.mp3', 'https://drive.google.com/file/d/1dRDD7KtiWjVtErOt6iD3rJEQJhfrXpzw/preview', 1761237844, 1761237844),
(46380, 'Judges 3:2', 'Judges', 3, 2, 'هغه د دې دپاره دا کار وکړ چې د اسراییلو هر نوی نسل باید دا زده کړي چې څنګه جګړه وکړي، په ځانګړې توګه هغه خلک چې مخکې د جګړې ډګر ته نه وو تللي.', 'هغه د دې دپاره دا کار وکر چې د اسراییلو هر نوی نسل باید دا زده کری چې چنګه جګره وکری، په جانګرې توګه هغه خلک چې مخکې د جګرې دګر ته نه وو تللی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges003_verse_002.mp3', 'https://drive.google.com/file/d/17aK-H6tn8ry5vVDiXZpa0yCNDC6Fj30d/preview', 1761237844, 1761237844),
(46381, 'Judges 3:3', 'Judges', 3, 3, 'هغه قومونه چې په دې خاوره کې پاتې شوي وو دا وو: هغه فلسطینیان چې په پنځو ښارونو کې وو، ټول کنعانیان، صیدونیان او همدارنګه حویان چې د لبنان په غرونو کې د بعل حرمون څخه نیولې د حمات تر غاښي پورې اوسېدل.', 'هغه قومونه چې په دې خاوره کې پاتې شوی وو دا وو: هغه فلسطینیان چې په پنجو شارونو کې وو، تول کنعانیان، صیدونیان او همدارنګه حویان چې د لبنان په غرونو کې د بعل حرمون چخه نیولې د حمات تر غاشی پورې اوسېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges003_verse_003.mp3', 'https://drive.google.com/uc?id=1frY1dRVIn6VG8qqcGwkQ6AJRhrM9ms2W&export=download', 1761237844, 1761237844),
(46382, 'Judges 3:4', 'Judges', 3, 4, 'څښتن دا خلک د دې دپاره پریښي وو چې اسراییلیان ورباندې وازمایي او وګوري چې ایا هغوی د څښتن هغو حکمونو ته چې د موسی په وسیله د هغوی نیکونو ته ورکړل شوي وو، غاړه ږدي او که نه.', 'چشتن دا خلک د دې دپاره پریشی وو چې اسراییلیان ورباندې وازمایی او وګوری چې ایا هغوی د چشتن هغو حکمونو ته چې د موسی په وسیله د هغوی نیکونو ته ورکرل شوی وو، غاره زدی او که نه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/judges003_verse_004.mp3', 'https://drive.google.com/uc?id=1XmqEr8nM8MdBn0ynrFKBjQXS3EDYh30Y&export=download', 1761237844, 1761237844),
